@csrf_exempt
@never_cache
def ping(
    request: HttpRequest,
    code: UUID,
    check: Check | None = None,
    action: str = "success",
    exitstatus: int | None = None,
) -> HttpResponse:
    if check is None:
        try:
            check = Check.objects.get(code=code)
        except Check.DoesNotExist:
            return HttpResponseNotFound("not found")

    if exitstatus is not None and exitstatus > 255:
        return HttpResponseBadRequest("invalid url format")

    headers = request.META
    remote_addr = headers.get("HTTP_X_FORWARDED_FOR", headers["REMOTE_ADDR"])
    remote_addr = remote_addr.split(",")[0]

    # If remote_addr does not validate but appears to be in ipv4:port form
    # (like Azure App Service reports), then remove the port
    if not valid_ip(remote_addr):
        parts = remote_addr.split(".")
        if len(parts) == 4 and ":" in parts[-1]:
            remote_addr = remote_addr.split(":")[0]

    scheme = headers.get("HTTP_X_FORWARDED_PROTO", "http")
    method = headers["REQUEST_METHOD"]
    ua = headers.get("HTTP_USER_AGENT", "")
    body = request.body[: settings.PING_BODY_LIMIT]

    if exitstatus is not None and exitstatus > 0:
        action = "fail"

    if check.methods == "POST" and method != "POST":
        action = "ign"

    if action != "ign" and check.filter_http_body:
        body_text = body.decode()
        if check.failure_kw and match_keywords(body_text, check.failure_kw):
            action = "fail"
        elif check.success_kw and match_keywords(body_text, check.success_kw):
            action = "success"
        elif check.start_kw and match_keywords(body_text, check.start_kw):
            action = "start"
        elif check.filter_default_fail:
            action = "fail"
        else:
            action = "ign"

    rid, rid_str = None, request.GET.get("rid")
    if rid_str is not None:
        if not is_valid_uuid_string(rid_str):
            return HttpResponseBadRequest("invalid uuid format")
        rid = UUID(rid_str)

    check.ping(remote_addr, scheme, method, ua, body, action, rid, exitstatus)

    response = HttpResponse("OK")
    if settings.PING_BODY_LIMIT is not None:
        response["Ping-Body-Limit"] = str(settings.PING_BODY_LIMIT)
    response["Access-Control-Allow-Origin"] = "*"
    return response

def notify(self, flip: Flip, is_test: bool = False) -> str:
    if self.transport.is_noop(flip.new_status):
        return "no-op"

    n = Notification(channel=self)
    if is_test:
        # When sending a test notification we leave the owner field null.
        # (the passed check is a dummy, unsaved Check instance)
        pass
    else:
        n.owner = flip.owner

    n.check_status = flip.new_status
    n.error = "Sending"
    try:
        n.save()
    except IntegrityError:
        return "Channel or check does not exist any more"

    start, error, disabled = now(), "", self.disabled
    try:
        self.transport.notify(flip, notification=n)

    except transports.TransportError as e:
        disabled = True if e.permanent else disabled
        error = e.message

    Notification.objects.filter(id=n.id).update(error=error)
    Channel.objects.filter(id=self.id).update(
        last_notify=start,
        last_notify_duration=now() - start,
        last_error=error,
        disabled=disabled,
    )

    return error
